import React, { useState } from 'react';
import { FileSpreadsheet, Download, Upload, Check, X } from 'lucide-react';
import { animalService } from '../../services/api';
import toast from 'react-hot-toast';

/**
 * Toplu Excel / CSV İçe-Dışa Aktarma Sihirbazı
 * Çiftçilerin yüzlerce hayvan kaydını Excel/CSV şablonuyla saniyeler içinde yüklemesini sağlar.
 */
export default function BatchExcelModal({ isOpen, onClose, farmId, onImported }) {
  const [parsedRows, setParsedRows] = useState([]);
  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  // Örnek CSV Şablonunu İndirme
  const handleDownloadTemplate = () => {
    const csvContent = "data:text/csv;charset=utf-8," + 
      "name,code,species,breed,gender,birth_date,current_weight\n" +
      "Pamuk,K001,Keçi,Saanen,F,2024-03-15,45.5\n" +
      "Kral,K002,Keçi,Halep,M,2023-11-20,68.0\n" +
      "Sarıkız,S001,Sığır,Holstein,F,2022-05-10,540.0";
    
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "mfk_farm_hayvan_yukleme_sablonu.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    toast.success('CSV Şablonu indirildi!');
  };

  // CSV Dosyası Seçme ve Okuma
  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target.result;

      const lines = text.split('\n').filter(line => line.trim() !== '');
      if (lines.length <= 1) {
        toast.error('Dosya geçerli veri satırı içermiyor.');
        return;
      }

      const rows = [];
      // İlk satır başlıklar
      for (let i = 1; i < lines.length; i++) {
        const parts = lines[i].split(',').map(p => p.trim());
        if (parts.length >= 5) {
          rows.push({
            name: parts[0],
            code: parts[1],
            species: parts[2] || 'Keçi',
            breed: parts[3] || '',
            gender: (parts[4] || 'F').toUpperCase(),
            birth_date: parts[5] || new Date().toISOString().split('T')[0],
            current_weight: parts[6] ? parseFloat(parts[6]) : null
          });
        }
      }

      setParsedRows(rows);
      toast.success(`${rows.length} hayvan kaydı okundu ve hazırlandı.`);
    };
    reader.readAsText(file);
  };

  // Veritabanına Toplu Aktarım
  const handleProcessImport = async () => {
    if (parsedRows.length === 0) {
      toast.error('Aktarılacak kayıt bulunmuyor.');
      return;
    }

    setLoading(true);
    let successCount = 0;
    let failCount = 0;

    try {
      await Promise.all(
        parsedRows.map(async (row) => {
          try {
            await animalService.create(farmId, row);
            successCount++;
          } catch {
            failCount++;
          }
        })
      );

      if (successCount > 0) {
        toast.success(`${successCount} hayvan başarıyla aktarıldı.${failCount > 0 ? ` (${failCount} kayıt hatalı)` : ''}`);
        if (onImported) onImported();
        onClose();
      } else {
        toast.error('Kayıtlar aktarılamadı. Lütfen küpe numaralarını ve formatı kontrol edin.');
      }
    } catch {
      toast.error('Toplu aktarım sırasında beklenmedik hata oluştu.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-md z-50 flex items-center justify-center p-3 sm:p-4 animate-fade-in">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-xl overflow-hidden border border-slate-100 flex flex-col">
        {/* Üst Yönetici Başlık */}
        <div 
          className="p-5 text-white relative overflow-hidden"
          style={{ background: 'linear-gradient(135deg, #022c22 0%, #064e3b 50%, #0f172a 100%)' }}
        >
          <div className="absolute -right-8 -top-8 w-40 h-40 bg-emerald-400/10 rounded-full blur-2xl pointer-events-none" />
          
          <div className="flex items-center justify-between relative z-10">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-2xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center shadow-inner">
                <FileSpreadsheet className="w-5 h-5 text-emerald-300" />
              </div>
              <div>
                <div className="flex items-center gap-1.5">
                  <h3 className="font-black text-sm text-white tracking-tight">Toplu Excel / CSV İçe Aktarma</h3>
                  <span className="px-1.5 py-0.2 rounded-full text-[9px] font-black bg-emerald-400/20 text-emerald-300 border border-emerald-400/30">
                    SÜRÜ YÜKLEYİCİ
                  </span>
                </div>
                <p className="text-[11px] text-emerald-100/80 mt-0.5">Yüzlerce hayvanı şablon dosya ile saniyeler içinde yükleyin</p>
              </div>
            </div>

            <button 
              onClick={onClose} 
              className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 text-white/80 hover:text-white flex items-center justify-center transition-all"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        <div className="p-6 space-y-5">
          {/* Adım 1: Şablon İndir */}
          <div className="p-4 rounded-2xl bg-gray-50 border border-gray-200/70 flex items-center justify-between">
            <div>
              <h4 className="font-bold text-xs text-gray-800 uppercase tracking-wide">1. Adım: Hazır Şablonu Alın</h4>
              <p className="text-xs text-gray-500 mt-0.5">Doğru sütun başlıklarını içeren CSV taslağı</p>
            </div>
            <button
              onClick={handleDownloadTemplate}
              className="btn-secondary text-xs px-3 py-1.5 flex items-center gap-1.5 font-bold text-emerald-700 bg-white"
            >
              <Download className="w-3.5 h-3.5" /> Şablonu İndir
            </button>
          </div>

          {/* Adım 2: Dosya Yükle */}
          <div className="p-4 rounded-2xl border-2 border-dashed border-gray-200 text-center hover:border-emerald-500 transition-colors">
            <input
              type="file"
              accept=".csv, text/csv"
              onChange={handleFileUpload}
              className="hidden"
              id="csvFileInput"
            />
            <label htmlFor="csvFileInput" className="cursor-pointer block">
              <Upload className="w-8 h-8 mx-auto mb-2 text-gray-400" />
              <p className="text-xs font-bold text-gray-700">Doldurulan CSV Dosyasını Seçin</p>
              <p className="text-[11px] text-gray-400 mt-0.5">Excel veya LibreOffice ile düzenlenmiş .csv dosyası</p>
            </label>
          </div>

          {/* Okunan Veri Özeti */}
          {parsedRows.length > 0 && (
            <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-xl flex items-center justify-between text-xs text-emerald-800 font-bold">
              <span>✅ {parsedRows.length} kayıt aktarıma hazır</span>
              <span className="text-[10px] text-emerald-600 font-normal">Örn: {parsedRows[0].name} ({parsedRows[0].code})</span>
            </div>
          )}
        </div>

        <div className="p-4 bg-gray-50 border-t border-gray-100 flex items-center justify-end gap-2">
          <button onClick={onClose} className="btn-secondary text-xs px-4 py-2">
            İptal
          </button>
          <button
            onClick={handleProcessImport}
            disabled={parsedRows.length === 0 || loading}
            className="btn-primary text-xs px-5 py-2 disabled:opacity-50 flex items-center gap-1.5 bg-emerald-600 hover:bg-emerald-700"
          >
            {loading ? 'Aktarılıyor...' : <><Check className="w-4 h-4" /> Sisteme Aktar</>}
          </button>
        </div>
      </div>
    </div>
  );
}
